import { test, expect } from "@playwright/test";

// `domains/<d>/{studies,discussions}` are human-authored real files that sit
// beside the virtual views derived from `runs/`. The `_e2e_fixture` domain is
// generated by scripts/setup-e2e-fixtures.mjs.
const DOMAIN = "/research/domains/_e2e_fixture";

test.describe("Domain human-authored layer (studies / discussions)", () => {
  test("domain page lists studies and discussions", async ({ page }) => {
    await page.goto(DOMAIN);
    const main = page.locator("main");
    await expect(main.locator(`a[href="${DOMAIN}/studies"]`)).toBeVisible();
    await expect(main.locator(`a[href="${DOMAIN}/discussions"]`)).toBeVisible();
  });

  test("studies directory lists dated study folders", async ({ page }) => {
    await page.goto(`${DOMAIN}/studies`);
    await expect(
      page.locator(`main a[href="${DOMAIN}/studies/20000101-sample-study"]`),
    ).toBeVisible();
  });

  test("renders a study document", async ({ page }) => {
    await page.goto(`${DOMAIN}/studies/20000101-sample-study/index`);
    await expect(
      page.getByRole("heading", { name: "E2E Sample Study" }),
    ).toBeVisible();
  });

  test("renders a discussion document", async ({ page }) => {
    await page.goto(`${DOMAIN}/discussions/20000101-sample-discussion`);
    await expect(
      page.getByRole("heading", { name: "E2E Sample Discussion" }),
    ).toBeVisible();
  });
});
